//! This private boundary selects the pre-swap C++ implementation for fixed-source comparisons.
use anyhow::Result;
use std::sync::Arc;
use manifold_csg::Manifold as Engine;
pub use manifold_csg::{MeshGL,MeshGL64,MeshGLOptions,MeshGL64Options,OpType,reserve_ids};
pub const IMPLEMENTATION: &str = "private-cpp-reference-manifold-csg-0.4.1-parallel";
#[derive(Clone)]
pub struct Manifold(Arc<Engine>);
impl Manifold {
 pub fn status(&self)->Result<()>{self.0.status()?;Ok(())}
 pub fn from_meshgl(m:&MeshGL)->Result<Self>{Ok(Self(Arc::new(Engine::from_meshgl(m)?)))}
 pub fn from_meshgl64(m:&MeshGL64)->Result<Self>{Ok(Self(Arc::new(Engine::from_meshgl64(m)?)))}
 pub fn from_mesh_f32(v:&[f32],s:usize,i:&[u32])->Result<Self>{Ok(Self(Arc::new(Engine::from_mesh_f32(v,s,i)?)))}
 pub fn from_mesh_f64(v:&[f64],s:usize,i:&[u64])->Result<Self>{Ok(Self(Arc::new(Engine::from_mesh_f64(v,s,i)?)))}
 pub fn to_meshgl(&self)->MeshGL{self.0.to_meshgl()}
 pub fn to_meshgl64(&self)->MeshGL64{self.0.to_meshgl64()}
 pub fn to_mesh_f32(&self)->(Vec<f32>,usize,Vec<u32>){self.0.to_mesh_f32()}
 pub fn to_mesh_f64(&self)->(Vec<f64>,usize,Vec<u64>){self.0.to_mesh_f64()}
 pub fn batch_boolean(m:&[Self],op:OpType)->Self{Self(Arc::new(Engine::batch_boolean(&m.iter().map(|s|(*s.0).clone()).collect::<Vec<_>>(),op)))}
 pub fn batch_union(m:&[Self])->Self{Self::batch_boolean(m,OpType::Add)}
 pub fn union(&self,b:&Self)->Self{Self(Arc::new(self.0.union(&b.0)))}
 pub fn difference(&self,b:&Self)->Self{Self(Arc::new(self.0.difference(&b.0)))}
 pub fn intersection(&self,b:&Self)->Self{Self(Arc::new(self.0.intersection(&b.0)))}
 pub fn split(&self,b:&Self)->(Self,Self){let(a,b)=self.0.split(&b.0);(Self(Arc::new(a)),Self(Arc::new(b)))}
 pub fn split_by_plane(&self,n:[f64;3],o:f64)->(Self,Self){let(a,b)=self.0.split_by_plane(n,o);(Self(Arc::new(a)),Self(Arc::new(b)))}
 pub fn simplify(&self,t:f64)->Self{Self(Arc::new(self.0.simplify(t)))}
 pub fn as_original(&self)->Self{Self(Arc::new(self.0.as_original()))}
 pub fn decompose(&self)->Vec<Self>{self.0.decompose().into_iter().map(|m|Self(Arc::new(m))).collect()}
 pub fn volume(&self)->f64{self.0.volume()}
 pub fn surface_area(&self)->f64{self.0.surface_area()}
 pub fn num_tri(&self)->usize{self.0.num_tri()}
 pub fn num_vert(&self)->usize{self.0.num_vert()}
 pub fn min_gap(&self,b:&Self,t:f64)->f64{self.0.min_gap(&b.0,t)}
 pub fn bounds(&self)->Option<([f64;3],[f64;3])>{self.0.bounding_box().map(|b|(b.min(),b.max()))}
 pub fn transform(&self,m:&[f64;12])->Self{Self(Arc::new(self.0.transform(m)))}
 pub fn cube(x:f64,y:f64,z:f64,c:bool)->Self{Self(Arc::new(Engine::cube(x,y,z,c)))}
 pub fn sphere(r:f64,s:usize)->Self{Self(Arc::new(Engine::sphere(r,s as i32)))}
 pub fn translate(&self,x:f64,y:f64,z:f64)->Self{Self(Arc::new(self.0.translate(x,y,z)))}
 pub fn rotate(&self,x:f64,y:f64,z:f64)->Self{Self(Arc::new(self.0.rotate(x,y,z)))}
}

