#!/usr/bin/env node
// This private compiler wrapper substitutes only the engine boundary for the workload comparison.
import {spawnSync} from 'node:child_process';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../../..');
const [rustc,...args]=process.argv.slice(2);
if(args[args.indexOf('--crate-name')+1]==='hsm_manifold'){
 const index=args.findIndex(a=>a.endsWith('manifold/src/lib.rs'));
 if(index<0)throw Error('No engine boundary source in compiler arguments');
 args[index]=path.join(path.dirname(fileURLToPath(import.meta.url)),'cpp-reference.rs');
}
const r=spawnSync(rustc,args,{stdio:'inherit'});if(r.error)throw r.error;process.exit(r.status??1);
